import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }


    public static void main(String[] args) throws IOException {
        int n = nextInt(), q = nextInt();
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nextLong();
        long total = prefix[n], answer = 0;
        int at = 0;
        for (int k = 0; k < q; k++) {
            int target = nextInt() - 1;
            long distance = Math.abs(prefix[target] - prefix[at]);
            answer += Math.min(distance, total - distance); // shorter of the two arcs
            at = target;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}


func main() {
	n, q := readInt(), readInt()
	prefix := make([]int, n+1)
	for i := 0; i < n; i++ {
		prefix[i+1] = prefix[i] + readInt()
	}
	total, answer, at := prefix[n], 0, 0
	for k := 0; k < q; k++ {
		target := readInt() - 1
		distance := prefix[target] - prefix[at]
		if distance < 0 {
			distance = -distance
		}
		answer += min(distance, total-distance) // shorter of the two arcs
		at = target
	}
	fmt.Println(answer)
}
